const items = $input.all();
const output = [];

for (const item of items) {
  const raw = item.json.body || item.json;

  // Detect source channel and normalize fields
  const isDrive = Boolean(raw.mimeType || raw.name);
  const source = isDrive ? 'Google Drive Intake' : (raw.bot_source || raw.source || 'Google Meet via Read AI');

  let moduleType = 'credit';
  let entityName = 'New Applicant Entity';
  let headlineMetric = 'Awaiting Financial Extraction';
  let transcript = '';
  let docUrl = '';
  let docNote = '';

  if (isDrive) {
    entityName = (raw.name || 'Uploaded File').replace(/\.[^/.]+$/, '');
    headlineMetric = 'New Document Ingestion';
    docUrl = raw.webViewLink || '';
    docNote = `File: ${raw.name} (${raw.size || 'N/A'} bytes)`;
    transcript = raw.text_content || `[System]: Intake file ${raw.name} placed in Google Drive folder. Ready for review.`;

    // Detect module from file name keywords
    const nameLower = entityName.lower();
    if (nameLower.includes('sales') || nameLower.includes('lead') || nameLower.includes('bdr')) {
      moduleType = 'sales';
    } else if (nameLower.includes('cv') || nameLower.includes('resume') || nameLower.includes('hr') || nameLower.includes('candidate')) {
      moduleType = 'hr';
    }
  } else {
    // Meeting Bot Payload (Read AI / Fireflies / Zoom)
    entityName = raw.meeting_title || raw.title || raw.client_name || 'Commercial Prospect';
    headlineMetric = raw.headline_metric || raw.requested_facility || 'Discovery Call Review';
    transcript = raw.transcript || raw.summary || raw.full_text || '';
    docUrl = raw.recording_url || raw.meeting_url || '';
    docNote = raw.duration ? `Call Duration: ${raw.duration}` : 'Meeting Recording';
    moduleType = (raw.department || raw.module || 'credit').toLowerCase();
  }

  output.push({
    json: {
      module_type: moduleType,
      entity_name: entityName,
      headline_metric: headlineMetric,
      transcript: transcript,
      source_channel: source,
      doc_url: docUrl,
      doc_note: docNote,
      summary: `Automated ingestion from ${source}`,
      timestamp: new Date().toISOString()
    }
  });
}

return output;
